import json
from catalog.pricing import discounted
from catalog.search import matching
from catalog.inventory import reserve, STOCK
from catalog.shipping import charge, PARCEL_RATE
results = {}
try:
    discounted(100, 101)
except ValueError:
    results['discount_over_100_rejected'] = True
else:
    results['discount_over_100_rejected'] = False
results['case_insensitive_search'] = matching(['Fern Pot', 'moss ball'], 'FERN') == ['Fern Pot']
before = STOCK.copy()
try:
    reserve('moss-02', 1)
except ValueError:
    results['oversell_rejected_without_mutation'] = STOCK == before
else:
    results['oversell_rejected_without_mutation'] = False
actual = charge([('fern-01', 1), ('moss-02', 1)])
results['two_lines_in_one_parcel'] = {'expected': PARCEL_RATE, 'actual': actual, 'pass': actual == PARCEL_RATE}
print(json.dumps(results, sort_keys=True))
